const L = require('lv-automation').adsConsole;
// The caller must hold a valid Supabase user JWT (HS256, SUPABASE_JWT_SECRET). The admin role is checked in the next Postgres node (public.has_role).
return { json: L.parseRequest({ route: $json.route, headers: $json.headers || {}, body: $json.body || {} }, { jwtSecret: $env.SUPABASE_JWT_SECRET }) };

const L = require('lv-automation').adsConsole;
// confirm route: guardrails + mint a bound, single-use token. Apply routes: verify the token against the SERVER-normalised params.
// The go-live share comes from the cycles row loaded above; nothing the browser sends can widen a cap.
const sd = $getWorkflowStaticData('global');
const d = L.decide({ parsed: $('Parse request + verify caller (JWT)').item.json, ctx: $json, env: $env, blockedUntil: sd.metaBlockedUntil || 0 });
if (d.ok === true && d.mode === 'apply') return { json: d };
if (d.ok === true) return { json: { mode: 'respond', status: d.status, body: d.body } };
return { json: { mode: 'respond', status: d.status, body: d.body } };

// An empty result means the nonce is already in ads_write_log: the token was used before (CONFIRM_REUSED).
const d = $('Decide (admin, SMC target, caps, mint or verify token)').item.json;
if (!$json.log_id) return { json: { mode: 'respond', status: 409, body: { ok: false, code: 'CONFIRM_REUSED', message: 'confirmToken already used' } } };
return { json: { ...d, logId: $json.log_id } };

const L = require('lv-automation').adsConsole;
const d = $json;
const applied = await L.applyWrite({ d, env: $env });
const sd = $getWorkflowStaticData('global');
if (applied.blockedUntil) sd.metaBlockedUntil = applied.blockedUntil; // rate-limit back-off survives across webhook runs
return { json: { d, applied } };

const L = require('lv-automation').adsConsole;
const s = L.shape({ d: $json.d, applied: $json.applied });
return { json: { status: s.status, body: s.body, record: s.record } };

